%region 🔖️Kernel
% 🧰 One scratch pool shared by every family in this package: exactly one domain family runs at a
% time, so the option variables and the working registers are declared once and each family's own
% `%region 🔖️Keys-…` block documents which of them its key names bind.
\tl_new:N \l_semio_viz_dom_data_tl
\tl_new:N \l_semio_viz_dom_edges_tl
\tl_new:N \l_semio_viz_dom_id_tl
