%endregion 🔖️Survey

%region 🔖️Keys-election
% 🔑 `election` keys, l3keys family `semio / viz / family / election`. §70 places constituencies on
% a tile grid and reads the winning share, the swing and the seats from the same table.
% variant (tl)     catalogue slug, recorded by the registry
% data    (table)  constituency table                              default `demo-election`
% mode    (choice `tile|cartogram|swing`)                          default `tile`
% label   (column) constituency caption                            default `region`
% x, y    (column) grid place                                      default `x`, `y`
% value   (column) the tinted quantity                             default `share`
% delta   (column) the swing the arrows carry                      default `swing`
% size    (column) the quantity a cartogram tile sizes             default `seats`
% scheme  (choice `sequential|diverging|cyclic`)                    default `sequential`
% inset   (mm)     gap between two tiles                            default 0.6
% arrow   (mm)     arrow head length of a swing arrow               default 1.2
% gain    (mm)     length of a swing arrow at the greatest swing    default 4
% labels  (bool)   print constituency captions                      default false
\keys_define:nn { semio / viz / family / election } {
  data    .tl_set:N   = \l_semio_viz_dom_data_tl,
  mode    .tl_set:N   = \l_semio_viz_dom_mode_tl,
  label   .tl_set:N   = \l_semio_viz_dom_label_tl,
  x       .tl_set:N   = \l_semio_viz_dom_x_tl,
  y       .tl_set:N   = \l_semio_viz_dom_y_tl,
  value   .tl_set:N   = \l_semio_viz_dom_value_tl,
  delta   .tl_set:N   = \l_semio_viz_dom_second_tl,
  size    .tl_set:N   = \l_semio_viz_dom_edges_tl,
  scheme  .tl_set:N   = \l_semio_viz_dom_scheme_tl,
  inset   .fp_set:N   = \l_semio_viz_dom_gamma_fp,
  arrow   .fp_set:N   = \l_semio_viz_dom_beta_fp,
  gain    .fp_set:N   = \l_semio_viz_dom_alpha_fp,
  pad     .fp_set:N   = \l_semio_viz_dom_pad_fp,
  width   .fp_set:N   = \l_semio_viz_dom_width_fp,
  height  .fp_set:N   = \l_semio_viz_dom_height_fp,
  labels  .bool_set:N = \l_semio_viz_dom_labels_bool,
  unknown .code:n     = { },
}
%endregion 🔖️Keys-election

%region 🔖️Election
% 🗳️ One constituency tile in the active mode.
\cs_new_protected:Npn \semio_viz_dom_el_tile:n #1 {
  \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_x_tl }
    \l_semio_viz_dom_key_tl
  \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_y_tl }
    \l_semio_viz_dom_tmp_tl
  \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_value_tl }
    \l_semio_viz_dom_cell_tl
  \semio_viz_dom_tile_at:nn { \l_semio_viz_dom_key_tl } { \l_semio_viz_dom_tmp_tl }
  \str_case:VnF \l_semio_viz_dom_mode_tl
    {
      { cartogram } { \semio_viz_dom_el_disc:n {#1} }
      { swing } { \semio_viz_dom_el_swing:n {#1} }
    }
    { \semio_viz_dom_el_patch: }
  \bool_if:NT \l_semio_viz_dom_labels_bool {
    \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_label_tl }
      \l_semio_viz_dom_q_tl
    \semio_viz_g_text:nnnn { \l_semio_viz_dom_x_fp } { \l_semio_viz_dom_y_fp } { center }
      { \tl_use:N \l_semio_viz_dom_q_tl }
  }
}

% 🗳️ The choropleth tile: a square tinted by the winning share.
\cs_new_protected:Npn \semio_viz_dom_el_patch: {
  \semio_viz_g_rect:nnnnn
    { \l_semio_viz_dom_x_fp - \l_semio_viz_dom_e_fp / 2 + \l_semio_viz_dom_gamma_fp / 2 }
    { \l_semio_viz_dom_y_fp - \l_semio_viz_dom_e_fp / 2 + \l_semio_viz_dom_gamma_fp / 2 }
    { \l_semio_viz_dom_e_fp - \l_semio_viz_dom_gamma_fp }
    { \l_semio_viz_dom_e_fp - \l_semio_viz_dom_gamma_fp }
    {
      fill = \semio_viz_dom_ramp:n { \semio_viz_dom_unit:n { \l_semio_viz_dom_cell_tl } } ,
      draw = none
    }
}

% 🗳️ The cartogram tile: a disc whose area carries the seats and whose tint carries the share.
\cs_new_protected:Npn \semio_viz_dom_el_disc:n #1 {
  \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_edges_tl }
    \l_semio_viz_dom_q_tl
  \semio_viz_g_circle:nnnn { \l_semio_viz_dom_x_fp } { \l_semio_viz_dom_y_fp }
    {
      ( \l_semio_viz_dom_e_fp - \l_semio_viz_dom_gamma_fp ) / 2
      * sqrt ( max ( 0.1 , \l_semio_viz_dom_q_tl / max ( 1e-9 , \l_semio_viz_dom_hi_b_fp ) ) )
    }
    {
      fill = \semio_viz_dom_ramp:n { \semio_viz_dom_unit:n { \l_semio_viz_dom_cell_tl } } ,
      draw = semio-chrome-border-normal , line~width = \semio@stroke@hairline
    }
}

% 🗳️ The swing tile: an arrow whose direction and length carry the change since the last poll.
\cs_new_protected:Npn \semio_viz_dom_el_swing:n #1 {
  \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_second_tl }
    \l_semio_viz_dom_q_tl
  \semio_viz_g_rect:nnnnn
    { \l_semio_viz_dom_x_fp - \l_semio_viz_dom_e_fp / 2 + \l_semio_viz_dom_gamma_fp / 2 }
    { \l_semio_viz_dom_y_fp - \l_semio_viz_dom_e_fp / 2 + \l_semio_viz_dom_gamma_fp / 2 }
    { \l_semio_viz_dom_e_fp - \l_semio_viz_dom_gamma_fp }
    { \l_semio_viz_dom_e_fp - \l_semio_viz_dom_gamma_fp }
    {
      fill = \semio_viz_theme_ramp_diverging:n
        { \l_semio_viz_dom_q_tl / max ( 1e-9 , \l_semio_viz_dom_g_fp ) } ,
      draw = none
    }
  \semio_viz_dom_arrow:nnnnnn { \l_semio_viz_dom_x_fp }
    { \l_semio_viz_dom_y_fp - \l_semio_viz_dom_alpha_fp / 2 }
    {
      \l_semio_viz_dom_x_fp
      + \l_semio_viz_dom_alpha_fp * \l_semio_viz_dom_q_tl
        / max ( 1e-9 , \l_semio_viz_dom_g_fp )
    }
    { \l_semio_viz_dom_y_fp + \l_semio_viz_dom_alpha_fp / 2 }
    { \l_semio_viz_dom_beta_fp }
    {
      draw = semio-chrome-border-emphasized , fill = semio-chrome-border-emphasized ,
      line~width = \semio@stroke@hairline
    }
}

% 🗳️ election: taxonomy §70. The tile choropleth, the seat cartogram and the swing map, three
% readings of one constituency table.
\SemioVizFamily { election } {
  \semio_viz_dom_reset:
  \tl_set:Nn \l_semio_viz_dom_data_tl { demo-election }
  \tl_set:Nn \l_semio_viz_dom_mode_tl { tile }
  \tl_set:Nn \l_semio_viz_dom_label_tl { region }
  \tl_set:Nn \l_semio_viz_dom_x_tl { x }
  \tl_set:Nn \l_semio_viz_dom_y_tl { y }
  \tl_set:Nn \l_semio_viz_dom_value_tl { share }
  \tl_set:Nn \l_semio_viz_dom_second_tl { swing }
  \tl_set:Nn \l_semio_viz_dom_edges_tl { seats }
  \fp_set:Nn \l_semio_viz_dom_alpha_fp { 4 }
  \fp_set:Nn \l_semio_viz_dom_beta_fp { 1.2 }
  \fp_set:Nn \l_semio_viz_dom_gamma_fp { 0.6 }
  \bool_set_false:N \l_semio_viz_dom_labels_bool
  \keys_set:nn { semio / viz / family / election } {#1}
  \semio_viz_dom_frame:
  \semio_viz_dom_tile_load:
  \semio_viz_table_col_max:VVN \l_semio_viz_dom_data_tl \l_semio_viz_dom_edges_tl
    \l_semio_viz_dom_hi_b_fp
  \semio_viz_table_col_max:VVN \l_semio_viz_dom_data_tl \l_semio_viz_dom_second_tl
    \l_semio_viz_dom_g_fp
  \int_step_inline:nn { \l_semio_viz_dom_n_int } { \semio_viz_dom_el_tile:n {##1} }
}
%endregion 🔖️Election

%region 🔖️Keys-biology
% 🔑 `biology` keys, l3keys family `semio / viz / family / biology`. §34 reads a survey grid: how
% rich every plot is, and which taxon holds it.
% variant (tl)     catalogue slug, recorded by the registry
% data    (table)  survey grid                                     default `demo-biodiversity`
% mode    (choice `graduated|range`)                               default `graduated`
% label   (column) plot caption                                    default `cell`
% x, y    (column) grid place                                      default `x`, `y`
% value   (column) species richness                                default `richness`
% group   (column) the taxon holding the plot                      default `species`
% scheme  (choice `sequential|diverging|cyclic`)                    default `sequential`
% node    (mm)     greatest symbol radius                          default 2.6
% inset   (mm)     gap between two plots                           default 0.6
% labels  (bool)   print plot captions                             default false
\keys_define:nn { semio / viz / family / biology } {
  data    .tl_set:N   = \l_semio_viz_dom_data_tl,
  mode    .tl_set:N   = \l_semio_viz_dom_mode_tl,
  label   .tl_set:N   = \l_semio_viz_dom_label_tl,
  x       .tl_set:N   = \l_semio_viz_dom_x_tl,
  y       .tl_set:N   = \l_semio_viz_dom_y_tl,
  value   .tl_set:N   = \l_semio_viz_dom_value_tl,
  group   .tl_set:N   = \l_semio_viz_dom_group_tl,
  scheme  .tl_set:N   = \l_semio_viz_dom_scheme_tl,
  node    .fp_set:N   = \l_semio_viz_dom_alpha_fp,
  inset   .fp_set:N   = \l_semio_viz_dom_gamma_fp,
  pad     .fp_set:N   = \l_semio_viz_dom_pad_fp,
  width   .fp_set:N   = \l_semio_viz_dom_width_fp,
  height  .fp_set:N   = \l_semio_viz_dom_height_fp,
  labels  .bool_set:N = \l_semio_viz_dom_labels_bool,
  unknown .code:n     = { },
}
%endregion 🔖️Keys-biology

%region 🔖️Biology
% 🌿 The graduated survey: one disc per plot, its area the richness recorded there.
\cs_new_protected:Npn \semio_viz_dom_bi_plot:n #1 {
  \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_x_tl }
    \l_semio_viz_dom_key_tl
  \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_y_tl }
    \l_semio_viz_dom_tmp_tl
  \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_value_tl }
    \l_semio_viz_dom_cell_tl
  \semio_viz_dom_tile_at:nn { \l_semio_viz_dom_key_tl } { \l_semio_viz_dom_tmp_tl }
  \semio_viz_g_circle:nnnn { \l_semio_viz_dom_x_fp } { \l_semio_viz_dom_y_fp }
    {
      \l_semio_viz_dom_alpha_fp
      * sqrt ( max ( 0.08 , \semio_viz_dom_unit:n { \l_semio_viz_dom_cell_tl } ) )
    }
    {
      fill = \semio_viz_dom_ramp:n { \semio_viz_dom_unit:n { \l_semio_viz_dom_cell_tl } } ,
      draw = semio-chrome-border-normal , line~width = \semio@stroke@hairline
    }
  \bool_if:NT \l_semio_viz_dom_labels_bool {
    \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_label_tl }
      \l_semio_viz_dom_q_tl
    \semio_viz_g_text:nnnn { \l_semio_viz_dom_x_fp }
      { \l_semio_viz_dom_y_fp + \l_semio_viz_dom_alpha_fp + 0.5 } { south }
      { \tl_use:N \l_semio_viz_dom_q_tl }
  }
}

% 🐾 The range map: the plots of one taxon tinted, and their extent closed into a range hull.
\cs_new_protected:Npn \semio_viz_dom_bi_ranges: {
  \semio_viz_dom_levels:VVN \l_semio_viz_dom_data_tl \l_semio_viz_dom_group_tl
    \l_semio_viz_dom_rowlev_seq
  \int_zero:N \l_semio_viz_dom_k_int
  \seq_map_inline:Nn \l_semio_viz_dom_rowlev_seq
    { \int_incr:N \l_semio_viz_dom_k_int \semio_viz_dom_bi_range:n {##1} }
}

% 🐾 One taxon range: its patches, then the rectangle its patches span.
\cs_new_protected:Npn \semio_viz_dom_bi_range:n #1 {
  \fp_set:Nn \l_semio_viz_dom_a_fp { 1e9 }
  \fp_set:Nn \l_semio_viz_dom_b_fp { -1e9 }
  \fp_set:Nn \l_semio_viz_dom_c_fp { 1e9 }
  \fp_set:Nn \l_semio_viz_dom_d_fp { -1e9 }
  \int_step_inline:nn { \l_semio_viz_dom_n_int } { \semio_viz_dom_bi_patch:nn {##1} {#1} }
  \semio_viz_g_rect:nnnnn
    { \l_semio_viz_dom_a_fp - \l_semio_viz_dom_e_fp / 2 + \l_semio_viz_dom_gamma_fp }
    { \l_semio_viz_dom_c_fp - \l_semio_viz_dom_e_fp / 2 + \l_semio_viz_dom_gamma_fp }
    {
      \l_semio_viz_dom_b_fp - \l_semio_viz_dom_a_fp + \l_semio_viz_dom_e_fp
      - 2 * \l_semio_viz_dom_gamma_fp
    }
    {
      \l_semio_viz_dom_d_fp - \l_semio_viz_dom_c_fp + \l_semio_viz_dom_e_fp
      - 2 * \l_semio_viz_dom_gamma_fp
    }
    {
      fill = none , draw = \semio_viz_palette:n { \l_semio_viz_dom_k_int } ,
      line~width = \semio@stroke@default , rounded~corners = 1mm
    }
  \bool_if:NT \l_semio_viz_dom_labels_bool {
    \semio_viz_g_text:nnnn
      { ( \l_semio_viz_dom_a_fp + \l_semio_viz_dom_b_fp ) / 2 }
      { \l_semio_viz_dom_d_fp + \l_semio_viz_dom_e_fp / 2 } { south } {#1}
  }
}

% 🐾 One plot of a taxon range; it also widens the range extent.
\cs_new_protected:Npn \semio_viz_dom_bi_patch:nn #1#2 {
  \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_group_tl }
    \l_semio_viz_dom_q_tl
  \str_if_eq:VnT \l_semio_viz_dom_q_tl {#2} {
    \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_x_tl }
      \l_semio_viz_dom_key_tl
    \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_y_tl }
      \l_semio_viz_dom_tmp_tl
    \semio_viz_table_cell:nnnN { \l_semio_viz_dom_data_tl } {#1} { \l_semio_viz_dom_value_tl }
      \l_semio_viz_dom_cell_tl
    \semio_viz_dom_tile_at:nn { \l_semio_viz_dom_key_tl } { \l_semio_viz_dom_tmp_tl }
    \fp_set:Nn \l_semio_viz_dom_a_fp { min ( \l_semio_viz_dom_a_fp , \l_semio_viz_dom_x_fp ) }
    \fp_set:Nn \l_semio_viz_dom_b_fp { max ( \l_semio_viz_dom_b_fp , \l_semio_viz_dom_x_fp ) }
    \fp_set:Nn \l_semio_viz_dom_c_fp { min ( \l_semio_viz_dom_c_fp , \l_semio_viz_dom_y_fp ) }
    \fp_set:Nn \l_semio_viz_dom_d_fp { max ( \l_semio_viz_dom_d_fp , \l_semio_viz_dom_y_fp ) }
    \semio_viz_g_rect:nnnnn
      { \l_semio_viz_dom_x_fp - \l_semio_viz_dom_e_fp / 2 + \l_semio_viz_dom_gamma_fp / 2 }
      { \l_semio_viz_dom_y_fp - \l_semio_viz_dom_e_fp / 2 + \l_semio_viz_dom_gamma_fp / 2 }
      { \l_semio_viz_dom_e_fp - \l_semio_viz_dom_gamma_fp }
      { \l_semio_viz_dom_e_fp - \l_semio_viz_dom_gamma_fp }
      {
        fill = \semio_viz_palette:n { \l_semio_viz_dom_k_int } ,
        fill~opacity =
          \fp_eval:n
            { 0.18 + 0.55 * \semio_viz_dom_unit:n { \l_semio_viz_dom_cell_tl } } ,
        draw = none
      }
  }
}

% 🌱 biology: taxonomy §34. The graduated biodiversity survey and the taxon range map, two
% readings of one plot grid.
\SemioVizFamily { biology } {
  \semio_viz_dom_reset:
  \tl_set:Nn \l_semio_viz_dom_data_tl { demo-biodiversity }
  \tl_set:Nn \l_semio_viz_dom_mode_tl { graduated }
  \tl_set:Nn \l_semio_viz_dom_label_tl { cell }
  \tl_set:Nn \l_semio_viz_dom_x_tl { x }
  \tl_set:Nn \l_semio_viz_dom_y_tl { y }
  \tl_set:Nn \l_semio_viz_dom_value_tl { richness }
  \tl_set:Nn \l_semio_viz_dom_group_tl { species }
  \fp_set:Nn \l_semio_viz_dom_alpha_fp { 2.6 }
  \fp_set:Nn \l_semio_viz_dom_gamma_fp { 0.6 }
  \bool_set_false:N \l_semio_viz_dom_labels_bool
  \keys_set:nn { semio / viz / family / biology } {#1}
  \semio_viz_dom_frame:
  \semio_viz_dom_tile_load:
  \str_if_eq:VnTF \l_semio_viz_dom_mode_tl { range }
    { \semio_viz_dom_bi_ranges: }
    { \int_step_inline:nn { \l_semio_viz_dom_n_int } { \semio_viz_dom_bi_plot:n {##1} } }
}
%endregion 🔖️Biology

\ExplSyntaxOff

semio-viz-data.sty.source:
\NeedsTeXFormat{LaTeX2e}
\ProvidesPackage{semio-viz-data}[2026/08/18 v0.1.0 semio viz data]

\RequirePackage{expl3}
\RequirePackage{xparse}

\ExplSyntaxOn
% 🧬 Typed row tokens preserve null and booleans independently of authored strings.
\NewDocumentCommand \SemioVizNull { } { }
\NewDocumentCommand \SemioVizString { m } {#1}
\NewDocumentCommand \SemioVizUndefined { } { }
\NewDocumentCommand \SemioVizNaN { } { }
\NewDocumentCommand \SemioVizBoolean { m } {#1}

% 🧾 Decodes one canonical string carrier for semantic scalar consumers without changing its payload.
\cs_new_protected:Npn \semio_viz_table_scalar_string:w \SemioVizString #1 \q_stop #2
  { \tl_set:Nn #2 {#1} }
\cs_new_protected:Npn \semio_viz_table_scalar:N #1 {
  \tl_if_head_eq_meaning:VNTF #1 \SemioVizString
    { \exp_after:wN \semio_viz_table_scalar_string:w #1 \q_stop #1 } { }
}

%region 🔖️Diagnostics
\msg_new:nnn { semio-viz } { unknown-table }
  { Unknown~viz~table~'#1'. }
\msg_new:nnn { semio-viz } { unknown-column }
  { Unknown~column~'#2'~in~table~'#1'. }
\msg_new:nnn { semio-viz } { empty-data }
  { Viz~table~'#1'~has~no~rows. }
\msg_new:nnn { semio-viz } { unknown-pointset }
  { Unknown~viz~point~set~'#1'.~Declare~it~with~\SemioVizPointSet. }
\msg_new:nnn { semio-viz } { unknown-grid }
  { Unknown~viz~grid~'#1'.~Declare~it~with~\SemioVizValueGrid. }
\msg_new:nnn { semio-viz } { unknown-geometry }
  { Unknown~viz~geometry~collection~'#1'.~Declare~it~with~\SemioVizGeoCollection. }
%endregion 🔖️Diagnostics

%region 🔖️Tables
\seq_new:N \g_semio_viz_table_names_seq
\tl_new:N \l_semio_viz_cell_tl
\int_new:N \l_semio_viz_col_int
\int_new:N \l_semio_viz_row_int

% 🏷️ Name of the sequence holding the rows of table #1.
\cs_new_protected:Npn \semio_viz_table_cs:n #1 { g_semio_viz_table_ \tl_to_str:n {#1} _rows_seq }
% 🏷️ Name of the comma list holding the column names of table #1.
\cs_new_protected:Npn \semio_viz_table_cols_cs:n #1 { g_semio_viz_table_ \tl_to_str:n {#1} _cols_clist }

\tl_new:N \l_semio_viz_tab_tl
\tl_new:N \l_semio_viz_colname_tl

% 📌 Fully expands the table name #1 once, so every csname built from it afterwards is the same.
\cs_new_protected:Npn \semio_viz_table_bind:n #1 {
  \tl_set:Nx \l_semio_viz_tab_tl {#1}
}
% 📌 The same for a column name, so a column given through a variable resolves once.
\cs_new_protected:Npn \semio_viz_table_bind_col:n #1 {
  \tl_set:Nx \l_semio_viz_colname_tl {#1}
}

% 🔒 Binds table #1 and stops with a diagnostic when no such table is declared.
\cs_new_protected:Npn \semio_viz_table_require:n #1 {
  \semio_viz_table_bind:n {#1}
  \exp_args:NV \semio_viz_table_require_chk:n \l_semio_viz_tab_tl
}
% 🔎 The check behind it, on the already-expanded name.
\cs_new_protected:Npn \semio_viz_table_require_chk:n #1 {
  \seq_if_in:NnF \g_semio_viz_table_names_seq {#1}
    { \msg_error:nnn { semio-viz } { unknown-table } {#1} }
}

% 📋 Declares table #1 with the column list #2; declaring an existing table empties it.
\cs_new_protected:Npn \semio_viz_table_new:nn #1#2 {
  \semio_viz_table_bind:n {#1}
  \exp_args:NV \semio_viz_table_new_aux:nn \l_semio_viz_tab_tl {#2}
}
% 🧱 The declaration itself, on the already-expanded name.
\cs_new_protected:Npn \semio_viz_table_new_aux:nn #1#2 {
  \seq_if_in:NnTF \g_semio_viz_table_names_seq {#1}
    {
      \seq_gclear:c { g_semio_viz_table_ #1 _rows_seq }
      \clist_gset:cn { g_semio_viz_table_ #1 _cols_clist } {#2}
    }
    {
      \seq_gput_right:Nn \g_semio_viz_table_names_seq {#1}
      \cs_if_exist:cF { g_semio_viz_table_ #1 _rows_seq } { \seq_new:c { g_semio_viz_table_ #1 _rows_seq } }
      \cs_if_exist:cF { g_semio_viz_table_ #1 _cols_clist } { \clist_new:c { g_semio_viz_table_ #1 _cols_clist } }
      \clist_gset:cn { g_semio_viz_table_ #1 _cols_clist } {#2}
    }
}

% ➕ Appends the comma-separated row #2 to table #1.
\cs_new_protected:Npn \semio_viz_table_row:nn #1#2 {
  \semio_viz_table_require:n {#1}
  \seq_gput_right:cn { g_semio_viz_table_ \l_semio_viz_tab_tl _rows_seq } {#2}
}

% 🔢 Number of rows of table #1, into the integer #2.
\cs_new_protected:Npn \semio_viz_table_nrows:nN #1#2 {
  \semio_viz_table_require:n {#1}
  \int_set:Nn #2 { \seq_count:c { g_semio_viz_table_ \l_semio_viz_tab_tl _rows_seq } }
}

% 🔎 1-based position of column #2 in table #1, zero when the table does not declare it.
%    Silent: the caller decides whether an absent column is an error or an empty cell.
\cs_new_protected:Npn \semio_viz_table_col_find:nnN #1#2#3 {
  \semio_viz_table_require:n {#1}
  \semio_viz_table_bind_col:n {#2}
  \int_zero:N #3
  \int_zero:N \l_tmpa_int
  \clist_map_inline:cn { g_semio_viz_table_ \l_semio_viz_tab_tl _cols_clist } {
    \int_incr:N \l_tmpa_int
    \tl_set:Nn \l_tmpb_tl {##1}
    \str_if_eq:VVT \l_semio_viz_colname_tl \l_tmpb_tl { \int_set_eq:NN #3 \l_tmpa_int }
  }
}

% ❓ True when table #1 declares a column named #2.
\prg_new_protected_conditional:Npnn \semio_viz_table_col_exist:nn #1#2 { T, F, TF } {
  \semio_viz_table_col_find:nnN {#1} {#2} \l_semio_viz_col_int
  \int_compare:nNnTF \l_semio_viz_col_int > { 0 } { \prg_return_true: } { \prg_return_false: }
}

% 🔎 The same position as `col_find`, but an absent column is an error: this is the accessor a
% renderer uses when the column is part of its contract.
\cs_new_protected:Npn \semio_viz_table_col_index:nnN #1#2#3 {
  \semio_viz_table_col_find:nnN {#1} {#2} #3
  \int_compare:nNnT #3 = { 0 }
    {
      \msg_error:nnxx { semio-viz } { unknown-column }
        { \tl_use:N \l_semio_viz_tab_tl } { \tl_use:N \l_semio_viz_colname_tl }
    }
}

\seq_new:N \l_semio_viz_row_seq
\tl_new:N \l_semio_viz_row_tl
\cs_generate_variant:Nn \seq_set_split:Nnn { NnV }

% 🧾 Loads row #2 of table #1 into \l_semio_viz_row_seq, one item per declared
% column: a comma list drops empty items, and an empty cell is exactly how a
% stratified table marks its root or a sparse matrix marks a hole.
\cs_new_protected:Npn \semio_viz_table_row_load:nn #1#2 {
  \semio_viz_table_require:n {#1}
  \tl_set:Nx \l_semio_viz_row_tl
    { \seq_item:cn { g_semio_viz_table_ \l_semio_viz_tab_tl _rows_seq } {#2} }
  \seq_set_split:NnV \l_semio_viz_row_seq { , } \l_semio_viz_row_tl
}

% 🧾 Cell #1 of the loaded row by column index; index zero is no column.
\cs_new_protected:Npn \semio_viz_table_row_cell:nN #1#2 {
  \int_compare:nNnTF {#1} > { 0 }
    { \tl_set:Nx #2 { \seq_item:Nn \l_semio_viz_row_seq {#1} } \tl_trim_spaces:N #2 }
    { \tl_clear:N #2 }
}

% 🧾 Column index of #2 in table #1; a blank column name is no column, a named one
%    that the table does not declare is an error.
\cs_new_protected:Npn \semio_viz_table_col_index_opt:nnN #1#2#3 {
  \tl_if_blank:nTF {#2}
    { \int_zero:N #3 }
    { \semio_viz_table_col_index:nnN {#1} {#2} #3 }
}

% 🧾 Cell (row #2, column #3) of table #1 into #4; a column the table does not declare is an error.
\cs_new_protected:Npn \semio_viz_table_cell:nnnN #1#2#3#4 {
  \semio_viz_table_col_index:nnN {#1} {#3} \l_semio_viz_col_int
  \semio_viz_table_row_load:nn {#1} {#2}
  \semio_viz_table_row_cell:nN { \l_semio_viz_col_int } #4
}

% 🧾 Cell (row #2, column #3) of table #1, empty when the table has no such column:
%    the reader for optional columns a family only uses when the data carries them.
\cs_new_protected:Npn \semio_viz_table_cell_opt:nnnN #1#2#3#4 {
  \semio_viz_table_col_find:nnN {#1} {#3} \l_semio_viz_col_int
  \int_compare:nNnTF \l_semio_viz_col_int = { 0 }
    { \tl_clear:N #4 }
    {
      \semio_viz_table_row_load:nn {#1} {#2}
      \semio_viz_table_row_cell:nN { \l_semio_viz_col_int } #4
    }
}

% 📉 Smallest value of column #2 of table #1 into #3; empty cells take no part.
\cs_new_protected:Npn \semio_viz_table_col_min:nnN #1#2#3 {
  \semio_viz_table_nrows:nN {#1} \l_semio_viz_row_int
  \fp_zero:N #3
  \int_compare:nNnF \l_semio_viz_row_int = { 0 } {
    \semio_viz_table_cell:nnnN {#1} { 1 } {#2} \l_semio_viz_cell_tl
    \tl_if_empty:NF \l_semio_viz_cell_tl { \fp_set:Nn #3 { \l_semio_viz_cell_tl } }
    \int_step_inline:nn { \l_semio_viz_row_int } {
      \semio_viz_table_cell:nnnN {#1} {##1} {#2} \l_semio_viz_cell_tl
      \tl_if_empty:NF \l_semio_viz_cell_tl {
        \fp_set:Nn #3 { \fp_eval:n { min(#3, \l_semio_viz_cell_tl) } }
      }
    }
  }
}

% 📈 Largest value of column #2 of table #1 into #3; an empty column leaves the unit maximum.
\cs_new_protected:Npn \semio_viz_table_col_max:nnN #1#2#3 {
  \semio_viz_table_nrows:nN {#1} \l_semio_viz_row_int
  \fp_set:Nn #3 { 1 }
  \int_compare:nNnF \l_semio_viz_row_int = { 0 } {
    \semio_viz_table_cell:nnnN {#1} { 1 } {#2} \l_semio_viz_cell_tl
    \tl_if_empty:NF \l_semio_viz_cell_tl { \fp_set:Nn #3 { \l_semio_viz_cell_tl } }
    \int_step_inline:nn { \l_semio_viz_row_int } {
      \semio_viz_table_cell:nnnN {#1} {##1} {#2} \l_semio_viz_cell_tl
      \tl_if_empty:NF \l_semio_viz_cell_tl {
        \fp_set:Nn #3 { \fp_eval:n { max(#3, \l_semio_viz_cell_tl) } }
      }
    }
  }
}

% ➕ Total of column #2 of table #1 into #3, counting the non-empty cells for the mean below.
\cs_new_protected:Npn \semio_viz_table_col_sum:nnN #1#2#3 {
  \semio_viz_table_nrows:nN {#1} \l_semio_viz_row_int
  \fp_zero:N #3
  \int_zero:N \l_tmpa_int
  \int_step_inline:nn { \l_semio_viz_row_int } {
    \semio_viz_table_cell:nnnN {#1} {##1} {#2} \l_semio_viz_cell_tl
    \tl_if_empty:NF \l_semio_viz_cell_tl {
      \fp_add:Nn #3 { \l_semio_viz_cell_tl }
      \int_incr:N \l_tmpa_int
    }
  }
}

% 🧮 Mean of column #2 of table #1 into #3, over its non-empty cells alone.
\cs_new_protected:Npn \semio_viz_table_col_mean:nnN #1#2#3 {
  \semio_viz_table_col_sum:nnN {#1} {#2} #3
  \int_compare:nNnTF \l_tmpa_int = { 0 }
    { \fp_zero:N #3 }
    { \fp_set:Nn #3 { \fp_eval:n { #3 / \l_tmpa_int } } }
}

% 🧪 Declares the generic `demo` table once, so any family can be drawn without a data set.
\cs_new_protected:Npn \semio_viz_data_demo: {
  \seq_if_in:NnF \g_semio_viz_table_names_seq { demo } {
    % 🧪 Columns beyond cat/val/val2/grp/t (label/from/to/row/col/chip/s1-3)
    % exist so the row-structured families rewritten off hand-placed TikZ
    % (grid/gantt/process/heat) still render real content from the generic
    % \SemioVizDemo{kind} gallery path, which always binds `data=demo`.
    \semio_viz_table_new:nn { demo } { cat, val, val2, grp, t, label, value, from, to, row, col, chip, s1, s2, s3 }
    \semio_viz_table_row:nn { demo } { A, 4, 2, x, 1, {Alpha},   4, A, B, R1, C1, Q1, {Stage 1}, {Stage 2}, {Stage 3} }
    \semio_viz_table_row:nn { demo } { B, 7, 3, x, 2, {Beta},    7, B, D, R1, C2, Q1, {Stage 1}, {Stage 2}, {Stage 3} }
    \semio_viz_table_row:nn { demo } { C, 3, 5, y, 3, {Gamma},   3, A, C, R2, C1, Q2, {Stage 1}, {Stage 2}, {Stage 3} }
    \semio_viz_table_row:nn { demo } { D, 8, 4, y, 4, {Delta},   8, C, E, R2, C2, Q2, {Stage 1}, {Stage 2}, {Stage 3} }
    \semio_viz_table_row:nn { demo } { E, 5, 6, x, 5, {Epsilon}, 5, B, E, R2, C3, Q3, {Stage 1}, {Stage 2}, {Stage 3} }
  }
}

\semio_viz_data_demo:

% 🪢 Declares shared outer and interior points so stock hulls demonstrate their distinct boundary algorithms.
\cs_new_protected:Npn \semio_viz_data_demo_hull: {
  \semio_viz_table_new:nn { demo-mark-hull } { t , val }
  \clist_map_inline:nn { {0,0},{4,0},{4,4},{0,4},{1,1},{3,1},{3,3},{1,3} }
    { \semio_viz_table_row:nn { demo-mark-hull } {##1} }
}
\semio_viz_data_demo_hull:

