      {8.3}{y}, {7.6}{y}, {9.1}{y}, {8.8}{y}, {7.9}{y}, {8.1}{y}, {9.6}{y}, {7.2}{y},
      {8.5}{y}, {9.3}{y}, {8.0}{y}, {7.7}{y}, {8.9}{y}, {9.8}{y}, {8.2}{y}, {7.4}{y},
      {8.6}{y}, {9.0}{y}, {7.8}{y}, {8.4}{y},
      {3.1}{z}, {2.6}{z}, {3.8}{z}, {2.9}{z}, {3.4}{z}, {2.2}{z}, {3.6}{z}, {2.8}{z}
    }
    { \semio_viz_data_demo_pair:nn { demo-distribution } {##1} }
}
% 📥 Unwraps a braced pair `{a}{b}` into a row of table #1.
\cs_new_protected:Npn \semio_viz_data_demo_pair:nn #1#2
  { \semio_viz_data_demo_pair_aux:nnn {#1} #2 }
% 📥 The two-field row it writes.
\cs_new_protected:Npn \semio_viz_data_demo_pair_aux:nnn #1#2#3
  { \semio_viz_table_row:nn {#1} { #2, #3 } }
% 📥 Unwraps a braced triple `{a}{b}{c}` into a row of table #1.
\cs_new_protected:Npn \semio_viz_data_demo_row:nn #1#2
  { \semio_viz_data_demo_row_aux:nnnn {#1} #2 }
% 📥 The three-field row it writes.
\cs_new_protected:Npn \semio_viz_data_demo_row_aux:nnnn #1#2#3#4
  { \semio_viz_table_row:nn {#1} { #2, #3, #4 } }
% 📥 Unwraps a braced quadruple `{a}{b}{c}{d}` into a row of table #1.
\cs_new_protected:Npn \semio_viz_data_demo_quad:nn #1#2
  { \semio_viz_data_demo_quad_aux:nnnnn {#1} #2 }
% 📥 The four-field row it writes.
\cs_new_protected:Npn \semio_viz_data_demo_quad_aux:nnnnn #1#2#3#4#5
  { \semio_viz_table_row:nn {#1} { #2, #3, #4, #5 } }

