% 📄 \SemioVizTableFromCSV{name}{file}[delimiter=,quote=,header=,columns=]: loads a table from disk.
\NewDocumentCommand \SemioVizTableFromCSV { m m O{} } { \semio_viz_data_csv:nnn {#1} {#2} {#3} }
% 🌳 \SemioVizHierarchy{name}[id=,parent=,value=,label=]: marks a table as a parent-linked hierarchy.
\NewDocumentCommand \SemioVizHierarchy { m O{} } { \semio_viz_data_hierarchy:nn {#1} {#2} }
% 🕸️ \SemioVizGraph{name}[source=,target=,weight=,nodes=,edges=]: marks a table as an edge list.
\NewDocumentCommand \SemioVizGraph { m O{} } { \semio_viz_data_graph:nn {#1} {#2} }
% 🔲 \SemioVizMatrix{name}[row=,col=,value=]: marks a table as a matrix in long form.
\NewDocumentCommand \SemioVizMatrix { m O{} } { \semio_viz_data_matrix:nn {#1} {#2} }
% 🗺️ \SemioVizGeometry{name}[ring=,lon=,lat=,label=]: marks a table as geographic rings.
\NewDocumentCommand \SemioVizGeometry { m O{} } { \semio_viz_data_geometry:nn {#1} {#2} }
% ➗ \SemioVizFunction{name}{expr}[domain=,samples=]: samples an fp expression in `x` into a table.
\NewDocumentCommand \SemioVizFunction { m m O{} } { \semio_viz_data_function:nnn {#1} {#2} {#3} }
%endregion 🔖️PublicApi

