%region 🔖️DemoData
% 🔢 Row counter of the generated demo tables; declared here because the tables are built while
% this region is read, before the option pool of the kernel region exists.
\int_new:N \l_semio_viz_dom_seed_int

% 🧪 One row per sprint: the four burn series, the resource capacity and the delivered velocity.
\cs_new_protected:Npn \semio_viz_dom_demo_sprint: {
  \seq_if_in:NnF \g_semio_viz_table_names_seq { demo-sprint } {
    \semio_viz_table_new:nn { demo-sprint }
      { t, remaining, completed, scope, wip, done, capacity, velocity }
    \clist_map_inline:nn
      {
        {1,60,0,60,4,0,14,0},{2,54,6,60,7,6,14,6},{3,45,15,62,9,15,16,9},
        {4,38,24,62,8,24,16,9},{5,28,36,64,11,36,18,12},{6,21,43,64,7,43,18,7},
        {7,12,54,66,9,54,15,11},{8,4,62,66,5,62,15,8}
      }
      { \semio_viz_table_row:nn { demo-sprint } {##1} }
  }
}

