    \clist_map_inline:nn
      {
        {P1,Housing,body,14,20,9,0,},
        {P2,Drive,gear,30,20,6,18,P1},
        {P3,Idler,gear,42,24,4,12,P2},
        {P4,Output,gear,53,19,5,15,P3},
        {P5,Crank,link,64,24,4,0,P4},
        {P6,Coupler,link,70,13,4,0,P5},
        {P7,Rocker,link,58,10,4,0,P6}
      }
      { \semio_viz_table_row:nn { demo-machine } {##1} }
  }
}

