    \clist_map_inline:nn
      {
        {edge,Edge,1,18,0.2},{auth,Auth,2,42,1.1},{api,API,2,31,0.4},
        {cart,Cart,3,64,2.3},{search,Search,3,88,0.7},{db,Store,4,120,0.1},
        {cache,Cache,4,9,0.0}
      }
      { \semio_viz_table_row:nn { demo-services } {##1} }
  }
  \seq_if_in:NnF \g_semio_viz_table_names_seq { demo-services-edges } {
    \semio_viz_table_new:nn { demo-services-edges } { source, target, calls }
    \clist_map_inline:nn
      {
        {edge,auth,120},{edge,api,340},{api,cart,210},{api,search,180},
        {cart,db,150},{search,cache,160},{auth,db,90},{cart,cache,60}
      }
      { \semio_viz_table_row:nn { demo-services-edges } {##1} }
  }
}

% 🧪 A four-channel activation tensor flattened to one row per cell.
\cs_new_protected:Npn \semio_viz_dom_demo_neural: {
  \seq_if_in:NnF \g_semio_viz_table_names_seq { demo-neural } {
    \semio_viz_table_new:nn { demo-neural } { channel, row, col, value }
    \int_step_inline:nnn { 1 } { 4 } {
      \int_step_inline:nnn { 1 } { 5 } {
        \int_step_inline:nnn { 1 } { 5 } {
          \semio_viz_table_row:nn { demo-neural }
            {
              ##1 , ####1 , ########1 ,
              \fp_eval:n
                { round ( sin ( ##1 + ####1 * 0.7 ) * cos ( ########1 * 0.6 - ##1 ) , 3 ) }
            }
        }
      }
    }
  }
}

% 🧪 Constituencies on a tile grid: the winning share, the swing since the last poll and the seats.
