  \tl_clear:N \l_semio_viz_dom_value_tl
  \tl_clear:N \l_semio_viz_dom_second_tl
  \tl_clear:N \l_semio_viz_dom_x_tl
  \tl_clear:N \l_semio_viz_dom_y_tl
